PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS tenants(id TEXT PRIMARY KEY,name TEXT NOT NULL,slug TEXT NOT NULL UNIQUE,status TEXT NOT NULL CHECK(status IN('ACTIVE','SUSPENDED')),reporting_currency TEXT NOT NULL DEFAULT 'USD',timezone TEXT NOT NULL DEFAULT 'Africa/Lagos',created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS users(id TEXT PRIMARY KEY,username TEXT NOT NULL UNIQUE,email TEXT UNIQUE,password_hash TEXT NOT NULL,first_name TEXT NOT NULL,middle_name TEXT,last_name TEXT NOT NULL,display_name TEXT NOT NULL,phone TEXT,timezone TEXT NOT NULL DEFAULT 'Africa/Lagos',preferred_currency TEXT NOT NULL DEFAULT 'USD',status TEXT NOT NULL CHECK(status IN('ACTIVE','SUSPENDED','INVITED')),is_platform_admin INTEGER NOT NULL DEFAULT 0,last_login_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS roles(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,name TEXT NOT NULL,description TEXT,created_at TEXT NOT NULL,UNIQUE(tenant_id,name),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS permissions(id TEXT PRIMARY KEY,code TEXT NOT NULL UNIQUE,description TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS role_permissions(role_id TEXT NOT NULL,permission_id TEXT NOT NULL,PRIMARY KEY(role_id,permission_id),FOREIGN KEY(role_id) REFERENCES roles(id),FOREIGN KEY(permission_id) REFERENCES permissions(id));
CREATE TABLE IF NOT EXISTS tenant_memberships(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,user_id TEXT NOT NULL,role_id TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE',created_at TEXT NOT NULL,UNIQUE(tenant_id,user_id),FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(user_id) REFERENCES users(id),FOREIGN KEY(role_id) REFERENCES roles(id));
CREATE TABLE IF NOT EXISTS auth_sessions(id TEXT PRIMARY KEY,user_id TEXT NOT NULL,token_hash TEXT NOT NULL UNIQUE,expires_at TEXT NOT NULL,revoked_at TEXT,created_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS user_preferences(user_id TEXT PRIMARY KEY,theme TEXT NOT NULL DEFAULT 'LIGHT',compact_tables INTEGER NOT NULL DEFAULT 0,default_tenant_id TEXT,updated_at TEXT NOT NULL,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS trading_accounts(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,account_name TEXT NOT NULL,account_number TEXT,broker TEXT,server TEXT,environment TEXT NOT NULL CHECK(environment IN('DEMO','LIVE','PROP_FIRM')),account_currency TEXT NOT NULL DEFAULT 'USD',balance REAL NOT NULL DEFAULT 0,equity REAL NOT NULL DEFAULT 0,free_margin REAL NOT NULL DEFAULT 0,margin REAL NOT NULL DEFAULT 0,leverage TEXT,status TEXT NOT NULL DEFAULT 'ACTIVE',connection_type TEXT NOT NULL DEFAULT 'LOCAL_MT5',connection_status TEXT NOT NULL DEFAULT 'DISCONNECTED',trading_enabled INTEGER NOT NULL DEFAULT 0,autonomous_trading_enabled INTEGER NOT NULL DEFAULT 0,last_synced_at TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS trading_connections(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,trading_account_id TEXT NOT NULL,adapter_type TEXT NOT NULL DEFAULT 'LOCAL_MT5',terminal_path TEXT,server_name TEXT,status TEXT NOT NULL DEFAULT 'DISCONNECTED',last_heartbeat_at TEXT,last_error TEXT,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(trading_account_id) REFERENCES trading_accounts(id));
CREATE TABLE IF NOT EXISTS account_risk_profiles(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,trading_account_id TEXT NOT NULL UNIQUE,max_open_positions INTEGER NOT NULL DEFAULT 3,max_total_risk_pct REAL NOT NULL DEFAULT 3.0,max_trade_risk_pct REAL NOT NULL DEFAULT 1.0,max_daily_loss_pct REAL,max_total_loss_pct REAL,profit_target_pct REAL,weekend_holding_allowed INTEGER NOT NULL DEFAULT 1,created_at TEXT NOT NULL,updated_at TEXT NOT NULL,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(trading_account_id) REFERENCES trading_accounts(id));
CREATE TABLE IF NOT EXISTS system_settings(key TEXT PRIMARY KEY,value_json TEXT NOT NULL,updated_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS tenant_settings(id TEXT PRIMARY KEY,tenant_id TEXT NOT NULL,key TEXT NOT NULL,value_json TEXT NOT NULL,updated_at TEXT NOT NULL,UNIQUE(tenant_id,key),FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS system_events(id TEXT PRIMARY KEY,tenant_id TEXT,event_type TEXT NOT NULL,entity_type TEXT,entity_id TEXT,correlation_id TEXT,payload_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL,FOREIGN KEY(tenant_id) REFERENCES tenants(id));
CREATE TABLE IF NOT EXISTS audit_events(id TEXT PRIMARY KEY,tenant_id TEXT,user_id TEXT,action TEXT NOT NULL,entity_type TEXT,entity_id TEXT,previous_json TEXT,new_json TEXT,reason TEXT,correlation_id TEXT,created_at TEXT NOT NULL,FOREIGN KEY(tenant_id) REFERENCES tenants(id),FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS security_events(id TEXT PRIMARY KEY,tenant_id TEXT,user_id TEXT,event_type TEXT NOT NULL,ip_address TEXT,user_agent TEXT,detail_json TEXT NOT NULL DEFAULT '{}',created_at TEXT NOT NULL);
CREATE TABLE IF NOT EXISTS worker_heartbeats(worker_name TEXT PRIMARY KEY,status TEXT NOT NULL,last_heartbeat_at TEXT NOT NULL,detail_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX IF NOT EXISTS idx_membership_tenant ON tenant_memberships(tenant_id,status);
CREATE INDEX IF NOT EXISTS idx_membership_user ON tenant_memberships(user_id,status);
CREATE INDEX IF NOT EXISTS idx_accounts_tenant ON trading_accounts(tenant_id,environment,status);
CREATE INDEX IF NOT EXISTS idx_connections_account ON trading_connections(trading_account_id,status);
CREATE INDEX IF NOT EXISTS idx_audit_tenant_created ON audit_events(tenant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_events_tenant_created ON system_events(tenant_id,created_at DESC);
CREATE INDEX IF NOT EXISTS idx_sessions_user_expiry ON auth_sessions(user_id,expires_at);
